package io.github.miklires.mcodes;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class CodeRepositoryTest{CodeRepository repo;@BeforeEach void open(){repo=new CodeRepository("jdbc:h2:mem:"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1");repo.initialize().join();}@AfterEach void close(){repo.close();}@Test void redeemIsAtomicAndOneTime(){var d=new CodeDefinition("welcome",CodeType.PROMO,null,1,1,null,List.of("give {player} diamond"),List.of());assertTrue(repo.create(d).join());UUID player=UUID.randomUUID();assertEquals(RedemptionResult.Status.ACCEPTED,repo.redeem("WELCOME",player,"Alex","").join().status());assertEquals(RedemptionResult.Status.LIMIT_REACHED,repo.redeem("WELCOME",UUID.randomUUID(),"Steve","").join().status());assertEquals(1,repo.pending().join().size());}@Test void selfReferralIsRejected(){UUID owner=UUID.randomUUID();repo.create(new CodeDefinition("alex",CodeType.REFERRAL,owner,0,1,null,List.of(),List.of())).join();assertEquals(RedemptionResult.Status.SELF_REFERRAL,repo.redeem("alex",owner,"Alex","").join().status());}}
